solution.solution.js:
function fizzBuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push("FizzBuzz");
    else if (i % 3 === 0) out.push("Fizz");
    else if (i % 5 === 0) out.push("Buzz");
    else out.push(String(i));
  }
  return out;
}

function dayType(day) {
  switch (day) {
    case "Sat":
    case "Sun":
      return "weekend";
    case "Mon":
    case "Tue":
    case "Wed":
    case "Thu":
    case "Fri":
      return "weekday";
    default:
      return "unknown";
  }
}

function collatzSteps(n) {
  let steps = 0;
  while (n !== 1) {
    n = n % 2 === 0 ? n / 2 : 3 * n + 1;
    steps++;
  }
  return steps;
}

unitTests:
test("fizz buzz", () => {
  checkEq(fizzBuzz(15), ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz", "11", "Fizz", "13", "14", "FizzBuzz"]);
  checkEq(fizzBuzz(0), []);
});

test("days", () => {
  checkEq(dayType("Sun"), "weekend");
  checkEq(dayType("Wed"), "weekday");
  checkEq(dayType("Funday"), "unknown");
});

test("collatz", () => {
  checkEq(collatzSteps(1), 0);
  checkEq(collatzSteps(6), 8);
  checkEq(collatzSteps(27), 111);
});

